def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    o=[row[:] for row in g]
    # find diagonal runs (length>=2) of same non-bg color, both diagonal directions
    seen=set()
    for d in (1,1),(-1,1):
        for r in range(h):
            for c in range(w):
                col=g[r][c]
                if col==bg or (r,c) in seen: continue
                run=[(r,c)]
                rr,cc=r+d,c+1
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==col:
                    run.append((rr,cc)); rr+=d; cc+=1
                if len(run)>=2:
                    for p in run: seen.add(p)
                    # extend both ends to border
                    rr,cc=run[0][0]-d,run[0][1]-1
                    while 0<=rr<h and 0<=cc<w:
                        o[rr][cc]=col; rr-=d; cc-=1
                    rr,cc=run[-1][0]+d,run[-1][1]+1
                    while 0<=rr<h and 0<=cc<w:
                        o[rr][cc]=col; rr+=d; cc+=1
    return o
